mapper.select:
SELECT messageId
FROM chatmessage_tbl
WHERE chatCode = #{chatCode}
AND messageId NOT IN (
SELECT messageId
FROM chatreceiver_tbl
WHERE userId = #{userId}
) and createAt >=
(SELECT createAt FROM chatparticipant_tbl where userId =#{userId} and chatCode = #{chatCode}) AND isRead = 0;

SELECT a.chatCode FROM bb.chat_tbl a JOIN ( SELECT chatCode FROM bb.chatparticipant_tbl WHERE userId IN
#{userId}
GROUP BY chatCode HAVING COUNT(DISTINCT userId) = 2 ) b ON a.chatCode = b.chatCode WHERE a.type = #{type}
